class Solution {
public:
    int subsequencesWithMiddleMode(vector<int>& nums) {
        const int MOD = 1e9 + 7;
        int n = nums.size();
        if (n < 5) return 0;

        unordered_map<int, int> left, right;
        for (int v : nums) right[v]++;

        auto nC2 = [](long long x) -> long long {
            return x >= 2 ? x * (x - 1) / 2 : 0;
        };

        long long Sr2 = 0, Sl2 = 0, Slr = 0, Slr2 = 0, Sl2r = 0;
        for (const auto& [_, c] : right) {
            Sr2 += nC2(c);
        }

        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            int x = nums[i];
            long long rxOld = right[x];
            long long lx = left[x];

            Sr2 -= (rxOld - 1);
            Slr -= lx;
            Slr2 -= lx * (2 * rxOld - 1);
            Sl2r -= lx * lx;
            right[x]--;
            long long rx = right[x];

            if (i >= 2 && n - 1 - i >= 2) {
                long long L = i, R = n - 1 - i;
                long long lo = L - lx, ro = R - rx;

                ans += nC2(lx) * nC2(rx);
                ans += nC2(lx) * rx * ro;
                ans += lx * lo * nC2(rx);
                ans += nC2(lx) * nC2(ro);
                ans += nC2(lo) * nC2(rx);
                ans += lx * lo * rx * ro;

                long long waysA = lx * lo * nC2(ro);
                long long waysB = nC2(lo) * rx * ro;

                long long sumRyC2 = Sr2 - nC2(rx);
                long long sumLyRy = Slr - lx * rx;
                long long sumLyRy2 = Slr2 - lx * rx * rx;
                long long badA = sumRyC2 * lo + ro * sumLyRy - sumLyRy2;

                long long sumLyC2 = Sl2 - nC2(lx);
                long long sumLy2Ry = Sl2r - lx * lx * rx;
                long long badB = sumLyC2 * ro + lo * sumLyRy - sumLy2Ry;

                ans += (waysA - badA) + (waysB - badB);
                ans %= MOD;
            }
            Sl2 += lx;
            Slr += rx;
            Slr2 += rx * rx;
            Sl2r += (2 * lx + 1) * rx;
            left[x]++;
        }
        return (ans % MOD + MOD) % MOD;
    }
};

class Solution {
    public int subsequencesWithMiddleMode(int[] nums) {
        int MOD = 1_000_000_007;
        int n = nums.length;
        if (n < 5) return 0;

        Map<Integer, Integer> left = new HashMap<>();
        Map<Integer, Integer> right = new HashMap<>();
        for (int v : nums) right.put(v, right.getOrDefault(v, 0) + 1);

        long Sr2 = 0, Sl2 = 0, Slr = 0, Slr2 = 0, Sl2r = 0;
        for (int c : right.values()) {
            if (c >= 2) Sr2 += (long)c * (c - 1) / 2;
        }

        long ans = 0;
        for (int i = 0; i < n; ++i) {
            int x = nums[i];
            long rxOld = right.get(x);
            long lx = left.getOrDefault(x, 0);

            Sr2 -= (rxOld - 1);
            Slr -= lx;
            Slr2 -= lx * (2 * rxOld - 1);
            Sl2r -= lx * lx;
            right.put(x, (int)rxOld - 1);
            long rx = rxOld - 1;

            if (i >= 2 && n - 1 - i >= 2) {
                long L = i, R = n - 1 - i;
                long lo = L - lx, ro = R - rx;

                ans += nC2(lx) * nC2(rx);
                ans += nC2(lx) * rx * ro;
                ans += lx * lo * nC2(rx);
                ans += nC2(lx) * nC2(ro);
                ans += nC2(lo) * nC2(rx);
                ans += lx * lo * rx * ro;

                long waysA = lx * lo * nC2(ro);
                long waysB = nC2(lo) * rx * ro;

                long sumRyC2 = Sr2 - nC2(rx);
                long sumLyRy = Slr - lx * rx;
                long sumLyRy2 = Slr2 - lx * rx * rx;
                long badA = sumRyC2 * lo + ro * sumLyRy - sumLyRy2;

                long sumLyC2 = Sl2 - nC2(lx);
                long sumLy2Ry = Sl2r - lx * lx * rx;
                long badB = sumLyC2 * ro + lo * sumLyRy - sumLy2Ry;

                ans += (waysA - badA) + (waysB - badB);
                ans %= MOD;
            }
            Sl2 += lx;
            Slr += rx;
            Slr2 += rx * rx;
            Sl2r += (2 * lx + 1) * rx;
            left.put(x, (int)lx + 1);
        }
        return (int)((ans % MOD + MOD) % MOD);
    }

    private long nC2(long x) {
        return x >= 2 ? x * (x - 1) / 2 : 0;
    }
}

var subsequencesWithMiddleMode = function(nums) {
    const MOD = 1000000007n;
    const n = nums.length;
    if (n < 5) return 0;

    const left = new Map();
    const right = new Map();
    for (const v of nums) right.set(v, (right.get(v) || 0) + 1);

    const nC2 = (x) => x >= 2n ? x * (x - 1n) / 2n : 0n;

    let Sr2 = 0n, Sl2 = 0n, Slr = 0n, Slr2 = 0n, Sl2r = 0n;
    for (const c of right.values()) {
        Sr2 += nC2(BigInt(c));
    }

    let ans = 0n;
    for (let i = 0; i < n; ++i) {
        const x = nums[i];
        const rxOld = BigInt(right.get(x));
        const lx = BigInt(left.get(x) || 0);

        Sr2 -= (rxOld - 1n);
        Slr -= lx;
        Slr2 -= lx * (2n * rxOld - 1n);
        Sl2r -= lx * lx;
        right.set(x, Number(rxOld - 1n));
        const rx = rxOld - 1n;

        if (i >= 2 && n - 1 - i >= 2) {
            const L = BigInt(i), R = BigInt(n - 1 - i);
            const lo = L - lx, ro = R - rx;

            ans += nC2(lx) * nC2(rx);
            ans += nC2(lx) * rx * ro;
            ans += lx * lo * nC2(rx);
            ans += nC2(lx) * nC2(ro);
            ans += nC2(lo) * nC2(rx);
            ans += lx * lo * rx * ro;

            const waysA = lx * lo * nC2(ro);
            const waysB = nC2(lo) * rx * ro;

            const sumRyC2 = Sr2 - nC2(rx);
            const sumLyRy = Slr - lx * rx;
            const sumLyRy2 = Slr2 - lx * rx * rx;
            const badA = sumRyC2 * lo + ro * sumLyRy - sumLyRy2;

            const sumLyC2 = Sl2 - nC2(lx);
            const sumLy2Ry = Sl2r - lx * lx * rx;
            const badB = sumLyC2 * ro + lo * sumLyRy - sumLy2Ry;

            ans += (waysA - badA) + (waysB - badB);
            ans %= MOD;
        }
        Sl2 += lx;
        Slr += rx;
        Slr2 += rx * rx;
        Sl2r += (2n * lx + 1n) * rx;
        left.set(x, Number(lx + 1n));
    }
    return Number((ans % MOD + MOD) % MOD);
};
